-- data-model.md sections 3.1-3.7. Generated by drizzle-kit, then reviewed and amended by hand BEFORE merge in two ways:
--   1. drizzle-kit qualifies foreign-key targets as "public"."table"; that is removed so the migration applies inside
--      whichever schema DB_SCHEMA selects through search_path (prod | staging | _aN in tests). migrate.test.ts fails
--      the build if any migration mentions the "public" schema again.
--   2. The trailing ALTER sets contract_saves.blob to EXTERNAL storage: the payload is already gzip-compressed, so
--      PostgreSQL must not spend CPU trying to pglz it again (data-model.md section 3.7).
-- Index justification: *_uq unique indexes serve token-hash / recovery-subject / invite-code lookups on the hot auth
-- and join paths; *_player_id_idx and *_family_id_idx serve cascade deletes and family revocation; expires_at and
-- last_seen_at / status+last_played serve the daily retention jobs; contract_members_player_last_seen_idx serves
-- "my Contracts". contract_saves has only its primary key (two rows per Contract, always looked up by id).
-- Forward-only; never edit after merge. The solo-save and lease columns come in 0002 (M1-W5-T07).
CREATE TABLE "contract_members" (
	"contract_id" uuid NOT NULL,
	"player_id" uuid NOT NULL,
	"role" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"joined_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_seen_at" timestamp with time zone DEFAULT now() NOT NULL,
	"playtime_s" bigint DEFAULT 0 NOT NULL,
	"banned_at" timestamp with time zone,
	"banned_by" uuid,
	"ban_reason" text,
	CONSTRAINT "contract_members_pk" PRIMARY KEY("contract_id","player_id"),
	CONSTRAINT "contract_members_role_check" CHECK ("contract_members"."role" in ('holder', 'supervisor', 'staff', 'temp')),
	CONSTRAINT "contract_members_status_check" CHECK ("contract_members"."status" in ('active', 'banned')),
	CONSTRAINT "contract_members_ban_reason_check" CHECK ("contract_members"."ban_reason" is null or "contract_members"."ban_reason" in ('griefing', 'harassment', 'cheating', 'other'))
);
