CREATE TABLE "contract_saves" (
	"contract_id" uuid NOT NULL,
	"slot" char(1) NOT NULL,
	"save_format_version" smallint NOT NULL,
	"game_data_version" text NOT NULL,
	"codec" text NOT NULL,
	"raw_size" integer NOT NULL,
	"blob_size" integer NOT NULL,
	"checksum" integer NOT NULL,
	"blob" "bytea" NOT NULL,
	"save_seq" bigint NOT NULL,
	"sim_tick" bigint NOT NULL,
	"saved_at" timestamp with time zone DEFAULT now() NOT NULL,
	"saved_by" text NOT NULL,
	CONSTRAINT "contract_saves_pk" PRIMARY KEY("contract_id","slot"),
